import {zipSync,strToU8} from 'fflate';
const escape=value=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
export function douyinFixture({headers=['作品名称','发布时间','审核状态','播放量','完播率','5s完播率','封面点击率','平均播放时长','点赞量','粉丝增量'],rows=[['合成测试作品A','2026-10-20 12:00:00','公开',0,{n:1,s:1},{n:.5,s:1},{n:.12,s:1},'1:05',null,-3],['合成测试作品B','2026-10-20 12:00:00','私密',123,'—',{n:.25,s:1},{n:0,s:1},'12.5',4,0]],shared=false,date1904=false}={}){
  const strings=[],cell=(v,index,line)=>{if(v==null)return '';const ref=String.fromCharCode(65+index)+line;if(typeof v==='object')return `<c r="${ref}" s="${v.s||0}">${v.formula?'<f>'+escape(v.formula)+'</f>':''}<v>${escape(v.n)}</v></c>`;if(typeof v==='number')return `<c r="${ref}"><v>${v}</v></c>`;if(shared){strings.push(v);return `<c r="${ref}" t="s"><v>${strings.length-1}</v></c>`;}return `<c r="${ref}" t="inlineStr"><is><t>${escape(v)}</t></is></c>`;};
  const sheet=`<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${[headers,...rows].map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>cell(v,j,i+1)).join('')}</row>`).join('')}</sheetData></worksheet>`;
  const files={
    '[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/active.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>',
    '_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
    'xl/workbook.xml':`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><workbookPr date1904="${date1904?1:0}"/><bookViews><workbookView activeTab="0"/></bookViews><sheets><sheet name="合成后台导出" sheetId="1" r:id="rId1"/></sheets></workbook>`,
    'xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/active.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>',
    'xl/styles.xml':'<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cellXfs count="3"><xf numFmtId="0"/><xf numFmtId="10"/><xf numFmtId="22"/></cellXfs></styleSheet>',
    'xl/worksheets/active.xml':sheet
  };
  if(shared)files['xl/sharedStrings.xml']='<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'+strings.map(s=>'<si><t>'+escape(s)+'</t></si>').join('')+'</sst>';
  return Buffer.from(zipSync(Object.fromEntries(Object.entries(files).map(([k,v])=>[k,strToU8(v)]))));
}
